svg.script:
(() => {
  const projectionAngle = Number(new URLSearchParams(location.search).get('t') || 0);
  if (Number.isFinite(projectionAngle) && Math.abs(projectionAngle) > 1e-9) return;

  let frameId = 0;
  let startedAt = 0;
  const qaTimeParam = new URLSearchParams(location.search).get('qaTime');
  const fixedQaSeconds = qaTimeParam === null ? null : Number(qaTimeParam);

  function rotate(id, angle) {
    const element = document.getElementById(id);
    if (!element) return;
    const x = element.dataset.pivotX;
    const y = element.dataset.pivotY;
    const transform = `rotate(${angle} ${x} ${y})`;
    element.setAttribute('transform', transform);

    const overlayByUpperArm = {
      'rig-arm-left-upper': ['walk-arm-left-overlay', 'rig-arm-left-forearm'],
      'rig-arm-right-upper': ['walk-arm-right-overlay', 'rig-arm-right-forearm'],
    };
    const overlayTarget = overlayByUpperArm[id];
    if (!overlayTarget) return;
    const overlay = document.getElementById(overlayTarget[0]);
    const forearm = document.getElementById(overlayTarget[1]);
    if (overlay?.contains(forearm)) overlay.setAttribute('transform', transform);
  }

  function setWalkFrontArm(frontSide) {
    const armParts = [
      ['left', 'rig-arm-left-upper', 'rig-arm-left-forearm', 'walk-arm-left-overlay'],
      ['right', 'rig-arm-right-upper', 'rig-arm-right-forearm', 'walk-arm-right-overlay'],
    ];

    for (const [side, upperId, forearmId, overlayId] of armParts) {
      const upper = document.getElementById(upperId);
      const forearm = document.getElementById(forearmId);
      const overlay = document.getElementById(overlayId);
      if (!upper || !forearm || !overlay) continue;

      if (side === frontSide) {
        overlay.setAttribute('transform', upper.getAttribute('transform'));
        if (forearm.parentNode !== overlay) overlay.appendChild(forearm);
      } else {
        if (forearm.parentNode !== upper) upper.appendChild(forearm);
        overlay.setAttribute('transform', `rotate(0 ${upper.dataset.pivotX} ${upper.dataset.pivotY})`);
      }
    }
  }

  function setWalkArmOcclusion(enabled) {
    setWalkFrontArm(enabled ? 'right' : null);
  }

  function positionLeg(id, x, y) {
    const element = document.getElementById(id);
    if (element) element.setAttribute('transform', `translate(${x} ${y})`);
  }

  function moveRoot(x, y) {
    document.getElementById('rig-person')?.setAttribute('transform', `translate(${x} ${y})`);
  }

  function resetPose() {
    cancelAnimationFrame(frameId);
    setWalkArmOcclusion(false);
    positionLeg('leg-left-offset', -8, 0);
    positionLeg('leg-right-offset', 8, 0);
    const rigPerson = document.getElementById('rig-person');
    if (rigPerson) {
      delete rigPerson.dataset.gaitMode;
      delete rigPerson.dataset.gaitStancePercent;
      delete rigPerson.dataset.gaitSwingPercent;
      delete rigPerson.dataset.flightPhase;
      delete rigPerson.dataset.doubleSupport;
      delete rigPerson.dataset.contactFoot;
      delete rigPerson.dataset.leftLegPhase;
      delete rigPerson.dataset.rightLegPhase;
      delete rigPerson.dataset.rootVertical;
      delete rigPerson.dataset.runState;
    }
    document.querySelectorAll('.rig[data-pivot-x][data-pivot-y]').forEach(element => {
      element.setAttribute('transform', `rotate(0 ${element.dataset.pivotX} ${element.dataset.pivotY})`);
    });
  }

  function animate(now) {
    const seconds = Number.isFinite(fixedQaSeconds)
      ? Math.max(0, fixedQaSeconds)
      : (now - startedAt) / 1000;
    const mode = location.hash.slice(1);

    if (mode === 'wave') {
      const wave = Math.sin(seconds * 7);
      const settle = Math.sin(seconds * 3.5);
      rotate('rig-arm-right-upper', -62 + settle * 3);
      rotate('rig-arm-right-forearm', -112 + wave * 16);
      rotate('rig-hand-right', wave * 20);
      rotate('rig-arm-left-upper', -4 - settle * 2);
      rotate('rig-hand-left', settle * 5);
      rotate('rig-leg-left-upper', settle * 0.5);
      rotate('rig-leg-right-upper', -settle * 0.5);
      rotate('rig-upper-body', -2 + settle * 1.5);
    } else if (mode === 'walk') {
      const halfStepDuration = 0.68;
      const loopTime = seconds % (halfStepDuration * 8);
      const halfStep = Math.floor(loopTime / halfStepDuration);
      const progress = (loopTime / halfStepDuration) - halfStep;
      const smoothstep = value => {
        const x = Math.max(0, Math.min(1, value));
        return x * x * (3 - 2 * x);
      };
      const doubleSupportEnd = 0.18;
      const swingPhase = Math.max(0, Math.min(1,
        (progress - doubleSupportEnd) / (1 - doubleSupportEnd)
      ));
      const swingArc = Math.sin(Math.PI * smoothstep(swingPhase));
      const leftIsPlanted = halfStep % 2 === 0;
      const rootY = -5 * Math.sin(Math.PI * progress);
      const rootX = (leftIsPlanted ? -1 : 1) * 3 * Math.sin(Math.PI * progress);
      const swingLift = 36 * swingArc;
      const leftLift = leftIsPlanted ? 0 : swingLift;
      const rightLift = leftIsPlanted ? swingLift : 0;
      const heelLift = 7 * swingArc;
      const armPhase = Math.cos(Math.PI * (halfStep + progress - 0.08));

      setWalkFrontArm(armPhase >= 0 ? 'right' : 'left');
      moveRoot(rootX, rootY);
      positionLeg('leg-left-offset', -8, -rootY - leftLift);
      positionLeg('leg-right-offset', 8, -rootY - rightLift);
      rotate('rig-leg-left-upper', 0);
      rotate('rig-leg-right-upper', 0);
      rotate('rig-leg-left-lower', leftIsPlanted ? 0 : -3 * swingArc);
      rotate('rig-leg-right-lower', leftIsPlanted ? 3 * swingArc : 0);
      rotate('rig-foot-left', leftIsPlanted ? 0 : heelLift + 3 * swingArc);
      rotate('rig-foot-right', leftIsPlanted ? -heelLift - 3 * swingArc : 0);
      rotate('rig-arm-left-upper', -armPhase * 6);
      rotate('rig-arm-right-upper', armPhase * 6);
      rotate('rig-arm-left-forearm', 0);
      rotate('rig-arm-right-forearm', 0);
      rotate('rig-upper-body', 0);
    } else if (mode === 'run') {
      const halfStepDuration = 0.33;
      const halfStepsPerLoop = 10;
      const dutyFactor = 0.28;
      const supportEnd = dutyFactor * 2;
      const loopTime = seconds % (halfStepDuration * halfStepsPerLoop);
      const halfStep = Math.floor(loopTime / halfStepDuration);
      const progress = (loopTime / halfStepDuration) - halfStep;
      const smoothstep = value => {
        const x = Math.max(0, Math.min(1, value));
        return x * x * (3 - 2 * x);
      };
      const leftIsContactLeg = halfStep % 2 === 0;
      const contactLegPhase = progress * 0.5;
      const otherLegPhase = 0.5 + progress * 0.5;

      const footLift = phase => {
        if (phase < dutyFactor) return 0;
        const swingProgress = Math.max(0, Math.min(1,
          (phase - dutyFactor) / (1 - dutyFactor)
        ));
        return 58 * Math.sin(Math.PI * swingProgress);
      };

      const stanceProgress = Math.min(1, progress / supportEnd);
      let rootY = -8 * Math.sin(Math.PI * stanceProgress);
      if (progress > supportEnd) {
        const flightProgress = (progress - supportEnd) / (1 - supportEnd);
        rootY = -18 * Math.sin(Math.PI * flightProgress);
      }

      const contactLift = footLift(contactLegPhase);
      const otherLift = footLift(otherLegPhase);
      const leftLift = leftIsContactLeg ? contactLift : otherLift;
      const rightLift = leftIsContactLeg ? otherLift : contactLift;
      positionLeg('leg-left-offset', -8, -leftLift - rootY);
      positionLeg('leg-right-offset', 8, -rightLift - rootY);
      moveRoot(0, rootY);
      rotate('rig-leg-left-upper', 0);
      rotate('rig-leg-right-upper', 0);
      const leftRecovery = Math.max(0, Math.min(1, leftLift / 58));
      const rightRecovery = Math.max(0, Math.min(1, rightLift / 58));
      rotate('rig-leg-left-lower', -14 * leftRecovery);
      rotate('rig-leg-right-lower', 14 * rightRecovery);
      rotate('rig-foot-left', 14 * leftRecovery);
      rotate('rig-foot-right', -14 * rightRecovery);

      const armPhase = Math.cos(Math.PI * (halfStep + progress));
      const frontArm = armPhase >= 0 ? 'right' : 'left';
      setWalkFrontArm(frontArm);
      rotate('rig-arm-left-upper', -armPhase * 10);
      rotate('rig-arm-right-upper', armPhase * 10);
      rotate('rig-arm-left-forearm', 0);
      rotate('rig-arm-right-forearm', 0);
      rotate('rig-upper-body', 0);

      const rigPerson = document.getElementById('rig-person');
      rigPerson.dataset.gaitMode = 'run';
      rigPerson.dataset.gaitStancePercent = '28';
      rigPerson.dataset.gaitSwingPercent = '72';
      rigPerson.dataset.flightPhase = String(progress > supportEnd);
      rigPerson.dataset.doubleSupport = 'false';
      rigPerson.dataset.contactFoot = progress > supportEnd
        ? 'none'
        : (leftIsContactLeg ? 'left' : 'right');
      rigPerson.dataset.leftLegPhase = (leftIsContactLeg ? contactLegPhase : otherLegPhase).toFixed(3);
      rigPerson.dataset.rightLegPhase = (leftIsContactLeg ? otherLegPhase : contactLegPhase).toFixed(3);
      rigPerson.dataset.rootVertical = rootY.toFixed(3);
      rigPerson.dataset.runState = JSON.stringify({
        halfStep,
        progress: Number(progress.toFixed(4)),
        flight: progress > supportEnd,
        contact: progress > supportEnd ? 'none' : (leftIsContactLeg ? 'left' : 'right'),
        rootY: Number(rootY.toFixed(3)),
        leftLift: Number(leftLift.toFixed(3)),
        rightLift: Number(rightLift.toFixed(3)),
        leftArm: Number((-armPhase * 10).toFixed(3)),
        rightArm: Number((armPhase * 10).toFixed(3))
      });
    } else {
      return;
    }

    if (!Number.isFinite(fixedQaSeconds)) {
      frameId = requestAnimationFrame(animate);
    }
  }

  function startMode() {
    resetPose();
    const mode = location.hash.slice(1);
    if (mode !== 'wave' && mode !== 'walk' && mode !== 'run') return;
    setWalkArmOcclusion(mode === 'walk' || mode === 'run');
    startedAt = performance.now();
    frameId = requestAnimationFrame(animate);
  }

  window.addEventListener('hashchange', startMode);
  startMode();
})();
